/* my_element — "Highlight Box" front-end styles. */

.my-element {
	border: 1px solid #d7dbe0;
	border-left: 4px solid #00b295; /* Unyson+ green accent */
	border-radius: 8px;
	padding: 16px 20px;
	background: #f7faf9;
}

.my-element--center { text-align: center; }
.my-element--right  { text-align: right; }

.my-element__heading {
	margin: 0 0 6px;
	font-size: 1.05rem;
	line-height: 1.3;
}

.my-element__text {
	margin: 0;
	color: #5f6266;
}
